<script>
  let klass = ''
  export { klass as class }
  export let role = 'cell'
  export let colspan = 1
  export let rowspan = 1

  let ariaColspan = colspan === 1 ? null : colspan
  let ariaRowspan = rowspan === 1 ? null : rowspan
</script>

<div
  {role}
  class="Cell Td {klass}"
  aria-colspan={ariaColspan}
  aria-rowspan={ariaRowspan}
  {...$$restProps}
>
  <slot />
</div>
